                name,
                resourceType,
                systemData,
                new VolumeProperties(
                    volumeId,
                    creationData,
                    sizeGiB,
                    storageTarget,
                    new ChangeTrackingList<ElasticSanManagedByInfo>(),
                    provisioningState,
                    null),
                null);
        }

        /// <summary> Response for Volume request. </summary>
        /// <param name="sizeGiB"> Volume size. </param>
